class Solution {
    public int removeDuplicates(int[] nums) {
        int[] unique = new int[nums.length];
        int size = 0;
        for (int value : nums) {
            if (size == 0 || unique[size - 1] != value) {
                unique[size++] = value;
            }
        }
        System.arraycopy(unique, 0, nums, 0, size);
        return size;
    }
}

